mapper.select:
WITH report_days AS (
SELECT CAST(#{day.date} AS DATE) AS report_date, #{day.startSecond} AS start_second, #{day.endSecond} AS end_second
), ledger_facts AS ( SELECT AS occurred_second, p.channel, p.currency, p.status AS payment_status, o.merchant_id IS NULL AS unattributed, 1 AS created_count, 0 AS paid_count, 0.00 AS received_amount, 0 AS refund_count, 0.00 AS refunded_amount, CASE WHEN p.status = 'SUCCESS' AND p.paid_at IS NULL THEN 1 ELSE 0 END AS missing_paid_at_count, 0 AS missing_refund_succeeded_at_count FROM payment_records p
WHERE >= #{startSecond} AND < #{endSecond}
UNION ALL SELECT , p.channel, p.currency, NULL, o.merchant_id IS NULL, 0, 1, p.amount, 0, 0.00, 0, 0 FROM payment_records p
WHERE p.status = 'SUCCESS' AND >= #{startSecond} AND < #{endSecond}
UNION ALL SELECT , p.channel, r.currency, NULL, o.merchant_id IS NULL, 0, 0, 0.00, 1, r.amount, 0, 0 FROM refund_records r JOIN payment_records p ON p.id = r.payment_id
WHERE r.status = 'SUCCEEDED' AND >= #{startSecond} AND < #{endSecond}
UNION ALL SELECT , p.channel, r.currency, NULL, o.merchant_id IS NULL, 0, 0, 0.00, 0, 0.00, 0, 1 FROM refund_records r JOIN payment_records p ON p.id = r.payment_id
WHERE r.status = 'SUCCEEDED' AND r.succeeded_at IS NULL AND >= #{startSecond} AND < #{endSecond}
) SELECT d.report_date, f.channel, f.currency, f.payment_status, f.unattributed, SUM(f.created_count) AS created_count, SUM(f.paid_count) AS paid_count, SUM(f.received_amount) AS received_amount, SUM(f.refund_count) AS refund_count, SUM(f.refunded_amount) AS refunded_amount, SUM(f.missing_paid_at_count) AS missing_paid_at_count, SUM(f.missing_refund_succeeded_at_count) AS missing_refund_succeeded_at_count FROM ledger_facts f JOIN report_days d ON f.occurred_second >= d.start_second AND f.occurred_second < d.end_second GROUP BY d.report_date, f.channel, f.currency, f.payment_status, f.unattributed ORDER BY d.report_date, f.channel, f.currency, f.payment_status, f.unattributed
